(function(){const cv=document.getElementById('emb'),x=cv.getContext('2d'),rm=matchMedia('(prefers-reduced-motion:reduce)').matches;let W,H,P=[];
function init(){const r=cv.getBoundingClientRect(),d=devicePixelRatio||1;W=r.width;H=r.height;cv.width=W*d;cv.height=H*d;x.setTransform(d,0,0,d,0,0);P=Array.from({length:W<600?24:46},()=>({x:Math.random()*W,y:Math.random()*H,r:Math.random()*2+.6,v:Math.random()*.5+.15,a:Math.random()*6.28}))}
function draw(t){x.clearRect(0,0,W,H);P.forEach(p=>{if(!rm){p.y-=p.v;p.x+=Math.sin(t/1500+p.a)*.25;if(p.y<-10){p.y=H+10;p.x=Math.random()*W}}const g=.5+.5*Math.sin(t/600+p.a);x.fillStyle=`rgba(255,120,40,${.25+.55*g})`;x.shadowColor='#ff6a1a';x.shadowBlur=10;x.beginPath();x.arc(p.x,p.y,p.r,0,6.283);x.fill()});if(!rm)requestAnimationFrame(draw)}
init();addEventListener('resize',init);requestAnimationFrame(draw)})();
