document.body.appendChild(root);
const $$=s=>root.querySelector(s),launch=$$('.gb-launch'),tip=$$('#gbtip'),msgs=$$('.gb-msgs'),qr=$$('.gb-qr'),inp=$$('.gb-in input'),modes=$$('.gb-modes');
let mode='school',stage=null,lead={},busy=false,opened=false,seq=0,qi=0;
modes.innerHTML=Object.keys(KB).map(k=>'<button type="button" role="tab" data-m="'+k+'">'+KB[k].label+'</button>').join('');
const avs=[...root.querySelectorAll('.gb-av,.gb-launch')];
function state(c,on){avs.forEach(a=>a.classList.toggle(c,on))}
function add(c,t,html){const d=document.createElement('div');d.className='gb-m '+c;if(html)d.innerHTML=t;else d.textContent=t;msgs.appendChild(d);const sd=()=>msgs.scrollTo({top:msgs.scrollHeight});sd();setTimeout(sd,120);setTimeout(sd,450);return d}
function btns(list,cta,more){qr.innerHTML='';list.forEach((t,i)=>{const b=document.createElement('button');b.type='button';b.textContent=t;b.style.animationDelay=i*70+'ms';if(cta&&i===0)b.className='cta';qr.appendChild(b)});if(more){const m=document.createElement('button');m.type='button';m.textContent='More \u279c';m.className='more';m.dataset.more='1';m.style.animationDelay=list.length*70+'ms';qr.appendChild(m)}}
function say(t,after,html){const id=++seq;busy=true;qr.innerHTML='';const tp=add('t','<i></i><i></i><i></i>',true);state('thinking',true);setTimeout(()=>{if(id!==seq)return;tp.remove();state('thinking',false);state('talking',true);add('b',t,html);setTimeout(()=>state('talking',false),Math.min(2200,t.length*22));busy=false;after&&after()},650+Math.min(700,t.length*6))}
const nq=x=>x.toLowerCase().trim().replace(/[?!.]+$/,'');
function chips(skip){const q=KB[mode].qr.filter(x=>nq(x)!==skip),o=[];for(let i=0;i<Math.min(4,q.length);i++)o.push(q[(qi+i)%q.length]);return o}
function menu(skip,adv){const n=KB[mode].qr.length;if(adv)qi=(qi+4)%n;btns([KB[mode].cta].concat(chips(skip)),true,n>5)}
function setMode(m){mode=m;stage=null;lead={};qi=0;ulang='en';seq++;msgs.innerHTML='';modes.querySelectorAll('button').forEach(b=>{const on=b.dataset.m===m;b.classList.toggle('on',on);b.setAttribute('aria-selected',on);if(on&&modes.scrollTo)modes.scrollTo({left:Math.max(0,b.offsetLeft-60),behavior:'smooth'})});say(KB[m].greet,menu)}
function open(m){root.classList.add('open');launch.setAttribute('aria-expanded','true');tip.classList.remove('show');opened=true;if(m&&m!==mode||!msgs.children.length)setMode(m||mode);setTimeout(()=>inp.focus({preventScroll:true}),400)}
function close(){root.classList.remove('open');launch.setAttribute('aria-expanded','false');tip.classList.add('show')}
const RU=/\b(kya|kaise|kese|kaisay|hai|hain|hun|hoon|kab|kitna|kitni|kitne|chahiye|chahta|chahti|bata|batao|btao|bataen|mujhe|mera|meri|mere|aap|ap|nahi|nahin|shukriya|shukria|kahan|bachay|bachon|bacha|karun|karna|karen|ka|ki|ke|mein|aur|zaroor|ji|dakhla|baje)\b/i;
let ulang='en';
const P={
 name:{en:()=>mode==='school'?"Happy to set that up! A visit takes about 30 minutes: a campus tour, a chat with the coordinator, a look at the classrooms and time for your questions.\n\nWhat is your name?":'Happy to set that up. What is your name?',ur:()=>mode==='school'?"Zaroor! Visit takriban 30 minute ki hoti hai: campus tour, coordinator se mulaqat, classrooms ka muaina aur aap ke sawalat.\n\nAap ka naam kya hai?":'Zaroor! Aap ka naam kya hai?'},
 grade:{en:f=>'Nice to meet you, '+f+'! Which class is your child applying for?',ur:f=>'Khushi hui, '+f+'! Aap ka bacha kis class mein admission lena chahta hai?'},
 day:{en:()=>KB[mode].dayQ?KB[mode].dayQ[0]:'Which day and time suits you for the visit? Visits run Monday to Friday, 9 am to 1 pm.',ur:()=>KB[mode].dayQ?KB[mode].dayQ[1]:'Visit ke liye kaun sa din aur time theek rahega? Visits Monday se Friday, subah 9 se dopahar 1 baje tak hoti hain.'},
 phone:{en:f=>'Thanks, '+f+'! What is the best phone or WhatsApp number to reach you on?',ur:f=>'Shukriya, '+f+'! Aap ka phone ya WhatsApp number kya hai jis par hum rabta kar saken?'}};
const SAY={hi:{en:'Hello! 😊 How can I help you today?',ur:'Assalam o Alaikum! 😊 Main aap ki kya madad kar sakta hoon?'},thx:{en:"You're welcome! Anything else I can help with?",ur:'Khushi hui! Kya main aur kisi cheez mein madad kar sakta hoon?'},short:{en:'That number looks too short. Please type it again with the area code, for example 0300 1234567.',ur:'Yeh number chhota lag raha hai. Barah-e-meharbani area code ke sath dobara likhein, masalan 0300 1234567.'},unsure:{en:"I want to get this right. Could you tell me a little more about what you need? You can also pick a topic below, or I can connect you with the team.",ur:'Main sahi jawab dena chahta hoon. Thora aur bata dein ke aap kya jaanna chahte hain? Aap neeche se topic bhi chun sakte hain, ya main aap ko team se connect kar doon.'}};
const g=(o,a)=>(o[ulang]||o.en)(a);
function reply(text){
 const t=text.toLowerCase().trim();
 if(stage==='phone'){const d=text.replace(/\D/g,'');if(d.length<7)return say(SAY.short[ulang]||SAY.short.en);lead.phone=text.trim().slice(0,30);stage=null;
  const f=lead.f,sub=encodeURIComponent(KB[mode].cta+' - '+lead.name),body=encodeURIComponent('Name: '+lead.name+'\nPhone: '+lead.phone+(lead.grade?'\nChild\'s class: '+lead.grade:'')+(lead.day?'\n'+(KB[mode].dayL||'Preferred visit time')+': '+lead.day:'')+'\nInterest: '+KB[mode].label+'\n\nSent from the website assistant.');
  const done=ulang==='ur'?'Shukriya, '+f+'! ✅ Maine '+lead.phone+' note kar liya hai. Team jald aap se rabta karegi. Details abhi bhejne ke liye <a href="mailto:'+MAIL+'?subject='+sub+'&body='+body+'">yahan tap karke email karein</a>.':'Thank you, '+f+'! ✅ I have noted '+lead.phone+(lead.grade?' for '+lead.grade:'')+(lead.day?' ('+lead.day+')':'')+'. The team will contact you shortly. To send your details right now, <a href="mailto:'+MAIL+'?subject='+sub+'&body='+body+'">tap here to email us</a>.';
  return say(done,menu,true)}
 if(stage){lead[stage]=text.trim().slice(0,60);if(stage==='name')lead.f=lead.name.split(' ')[0];const o=KB[mode].flow||['name','phone'];stage=o[o.indexOf(stage)+1];return say(g(P[stage],lead.f))}
 if(/\bbook(ed|ing)?\b|reserve|visit|demo|appointment|talk|human|team|call|contact|baat|rabta|start (a |my )?project/.test(t)){stage='name';return say(g(P.name))}
 if(/^(hi|hello|hey|salam|assalam|aoa|slam)\b/.test(t))return say(SAY.hi[ulang]||SAY.hi.en,menu);
 if(/thank|shukriya|shukria|jazak/.test(t))return say(SAY.thx[ulang]||SAY.thx.en,menu);
 const nt=nq(t),qa=KB[mode].qa,hit=qa.find(q=>q[0]===nt)||qa.find(q=>q[1].test(t)||t.includes(q[0]));
 if(hit){const ans=ulang==='ur'&&hit[3]?hit[3]:hit[2];return say(ans,()=>menu(hit[0],true),true)}
 say(SAY.unsure[ulang]||SAY.unsure.en,()=>menu())}
function send(t,btn){t=(t||inp.value).trim();if(!t||busy)return;inp.value='';add('u',t);if(!btn&&!stage)ulang=RU.test(t)?'ur':'en';reply(t)}
